mapper.select:

where abr.balance_record_id = #{balanceRecordId}
  and abr.del_flag = 0

    and abr.account_id = #{accountId}

select abr.balance_record_id as balanceRecordId, abr.account_id as accountId, a.nick_name as accountNickName, a.mobile as accountMobile, abr.record_type as recordType, abr.change_type as changeType, abr.change_amount as changeAmount, abr.balance_before as balanceBefore, abr.balance_after as balanceAfter, abr.biz_id as bizId, abr.biz_no as bizNo, abr.remark as remark, abr.create_time as createTime from account_balance_record abr left join account a on abr.account_id = a.account_id and a.del_flag = 0 where abr.del_flag = 0
and abr.account_id = #{accountId}
and a.nick_name like concat('%', #{accountNickName}, '%')
and a.mobile like concat('%', #{accountMobile}, '%')
and abr.record_type = #{recordType}
and abr.change_type = #{changeType}
and abr.biz_no like concat('%', #{bizNo}, '%')
and date_format(abr.create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
and date_format(abr.create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')
order by abr.balance_record_id desc


where abr.del_flag = 0

    and abr.account_id = #{accountId}


    and abr.record_type = #{recordType}


    and abr.change_type = #{changeType}

order by abr.balance_record_id desc
